insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('1sa-13-15','1sa','사무엘상',13,15,'사무엘이 일어나 길갈에서 떠나 베냐민 기브아로 올라가니라. 사울이 자기와 함께 한 백성의 수를 세어 보니 육백 명 가량이라',7501),
('1sa-13-16','1sa','사무엘상',13,16,'사울과 그의 아들 요나단과 그들과 함께 한 백성은 베냐민 게바에 있고 블레셋 사람들은 믹마스에 진 쳤더니',7502),
('1sa-13-17','1sa','사무엘상',13,17,'노략꾼들이 세 대로 블레셋 사람들의 진영에서 나와서 한 대는 오브라 길을 따라서 수알 땅에 이르렀고',7503),
('1sa-13-18','1sa','사무엘상',13,18,'한 대는 벧호론 길로 향하였고 한 대는 광야쪽으로 스보임 골짜기가 내려다 보이는 지역 길로 향하였더라',7504),
('1sa-13-19','1sa','사무엘상',13,19,'그 때에 이스라엘 온 땅에 철공이 없었으니 이는 블레셋 사람들이 말하기를 히브리 사람이 칼이나 창을 만들까 두렵다 하였음이라',7505),
('1sa-13-20','1sa','사무엘상',13,20,'온 이스라엘 사람들이 각기 보습이나 삽이나 도끼나 괭이를 벼리려면 블레셋 사람들에게로 내려갔었는데',7506),
('1sa-13-21','1sa','사무엘상',13,21,'곧 그들이 괭이나 삽이나 쇠스랑이나 도끼나 쇠채찍이 무딜 때에 그리하였으므로',7507),
('1sa-13-22','1sa','사무엘상',13,22,'싸우는 날에 사울과 요나단과 함께 한 백성의 손에는 칼이나 창이 없고 오직 사울과 그의 아들 요나단에게만 있었더라',7508),
('1sa-13-23','1sa','사무엘상',13,23,'블레셋 사람들의 부대가 나와서 믹마스 어귀에 이르렀더라',7509),
('1sa-14-1','1sa','사무엘상',14,1,'하루는 사울의 아들 요나단이 자기의 무기를 든 소년에게 이르되 우리가 건너편 블레셋 사람들의 부대로 건너가자 하고 그의 아버지에게는 아뢰지 아니하였더라',7510),
('1sa-14-2','1sa','사무엘상',14,2,'사울이 기브아 변두리 미그론에 있는 석류나무 아래에 머물렀고 함께 한 백성은 육백 명 가량이며',7511),
('1sa-14-3','1sa','사무엘상',14,3,'아히야는 에봇을 입고 거기 있었으니 그는 이가봇의 형제 아히둡의 아들이요 비느하스의 손자요 실로에서 여호와의 제사장이 되었던 엘리의 증손이었더라 백성은 요나단이 간 줄을 알지 못하니라',7512),
('1sa-14-4','1sa','사무엘상',14,4,'요나단이 블레셋 사람들에게로 건너가려 하는 어귀 사이 이쪽에는 험한 바위가 있고 저쪽에도 험한 바위가 있는데 하나의 이름은 보세스요 하나의 이름은 세네라',7513),
('1sa-14-5','1sa','사무엘상',14,5,'한 바위는 북쪽에서 믹마스 앞에 일어섰고 하나는 남쪽에서 게바 앞에 일어섰더라',7514),
('1sa-14-6','1sa','사무엘상',14,6,'요나단이 자기의 무기를 든 소년에게 이르되 우리가 이 할례 받지 않은 자들에게로 건너가자 여호와께서 우리를 위하여 일하실까 하노라 여호와의 구원은 사람이 많고 적음에 달리지 아니하였느니라',7515),
('1sa-14-7','1sa','사무엘상',14,7,'무기를 든 자가 그에게 이르되 당신의 마음에 있는 대로 다 행하여 앞서 가소서 내가 당신과 마음을 같이 하여 따르리이다',7516),
('1sa-14-8','1sa','사무엘상',14,8,'요나단이 이르되 보라 우리가 그 사람들에게로 건너가서 그들에게 보이리니',7517),
('1sa-14-9','1sa','사무엘상',14,9,'그들이 만일 우리에게 이르기를 우리가 너희에게로 가기를 기다리라 하면 우리는 우리가 있는 곳에 가만히 서서 그들에게로 올라가지 말 것이요',7518),
('1sa-14-10','1sa','사무엘상',14,10,'그들이 만일 말하기를 우리에게로 올라오라 하면 우리가 올라갈 것은 여호와께서 그들을 우리 손에 넘기셨음이니 이것이 우리에게 표징이 되리라 하고',7519),
('1sa-14-11','1sa','사무엘상',14,11,'둘이 다 블레셋 사람들에게 보이매 블레셋 사람이 이르되 보라 히브리 사람이 그들이 숨었던 구멍에서 나온다 하고',7520),
('1sa-14-12','1sa','사무엘상',14,12,'그 부대 사람들이 요나단과 그의 무기를 든 자에게 이르되 우리에게로 올라오라 너희에게 보여 줄 것이 있느니라 한지라 요나단이 자기의 무기를 든 자에게 이르되 나를 따라 올라오라 여호와께서 그들을 이스라엘의 손에 넘기셨느니라 하고',7521),
('1sa-14-13','1sa','사무엘상',14,13,'요나단이 손 발로 기어 올라갔고 그 무기를 든 자도 따랐더라 블레셋 사람들이 요나단 앞에서 엎드러지매 무기를 든 자가 따라가며 죽였으니',7522),
('1sa-14-14','1sa','사무엘상',14,14,'요나단과 그 무기를 든 자가 반나절 갈이 땅 안에서 처음으로 쳐죽인 자가 이십 명 가량이라',7523),
('1sa-14-15','1sa','사무엘상',14,15,'들에 있는 진영과 모든 백성들이 공포에 떨었고 부대와 노략꾼들도 떨었으며 땅도 진동하였으니 이는 큰 떨림이었더라',7524),
('1sa-14-16','1sa','사무엘상',14,16,'베냐민 기브아에 있는 사울의 파수꾼이 바라본즉 허다한 블레셋 사람들이 무너져 이리 저리 흩어지더라',7525),
('1sa-14-17','1sa','사무엘상',14,17,'사울이 자기와 함께 한 백성에게 이르되 우리에게서 누가 나갔는지 점호하여 보라 하여 점호한즉 요나단과 그의 무기를 든 자가 없어졌더라',7526),
('1sa-14-18','1sa','사무엘상',14,18,'사울이 아히야에게 이르되 하나님의 궤를 이리로 가져오라 하니 그 때에 하나님의 궤가 이스라엘 자손과 함께 있음이니라',7527),
('1sa-14-19','1sa','사무엘상',14,19,'사울이 제사장에게 말할 때에 블레셋 사람들의 진영에 소동이 점점 더한지라 사울이 제사장에게 이르되 네 손을 거두라 하고',7528),
('1sa-14-20','1sa','사무엘상',14,20,'사울과 그와 함께 한 모든 백성이 모여 전장에 가서 본즉 블레셋 사람들이 각각 칼로 자기의 동무들을 치므로 크게 혼란하였더라',7529),
('1sa-14-21','1sa','사무엘상',14,21,'전에 블레셋 사람들과 함께 하던 히브리 사람이 사방에서 블레셋 사람들과 함께 진영에 들어왔더니 그들이 돌이켜 사울과 요나단과 함께 한 이스라엘 사람들과 합하였고',7530),
('1sa-14-22','1sa','사무엘상',14,22,'에브라임 산지에 숨었던 이스라엘 모든 사람도 블레셋 사람들이 도망함을 듣고 싸우러 나와서 그들을 추격하였더라',7531),
('1sa-14-23','1sa','사무엘상',14,23,'여호와께서 그 날에 이스라엘을 구원하시므로 전쟁이 벧아웬을 지나니라',7532),
('1sa-14-24','1sa','사무엘상',14,24,'이 날에 이스라엘 백성들이 피곤하였으니 이는 사울이 백성에게 맹세시켜 경계하여 이르기를 저녁 곧 내가 내 원수에게 보복하는 때까지 아무 음식물이든지 먹는 사람은 저주를 받을지어다 하였음이라 그러므로 모든 백성이 음식물을 맛보지 못하고',7533),
('1sa-14-25','1sa','사무엘상',14,25,'그들이 다 수풀에 들어간즉 땅에 꿀이 있더라',7534),
('1sa-14-26','1sa','사무엘상',14,26,'백성이 수풀로 들어갈 때에 꿀이 흐르는 것을 보고도 그들이 맹세를 두려워하여 손을 그 입에 대는 자가 없었으나',7535),
('1sa-14-27','1sa','사무엘상',14,27,'요나단은 그의 아버지가 백성에게 맹세하여 명령할 때에 듣지 못하였으므로 손에 가진 지팡이 끝을 내밀어 벌집의 꿀을 찍고 그의 손을 돌려 입에 대매 눈이 밝아졌더라',7536),
('1sa-14-28','1sa','사무엘상',14,28,'그 때에 백성 중 한 사람이 말하여 이르되 당신의 부친이 백성에게 맹세하여 엄히 말씀하시기를 오늘 음식물을 먹는 사람은 저주를 받을지어다 하셨나이다 그러므로 백성이 피곤하였나이다 하니',7537),
('1sa-14-29','1sa','사무엘상',14,29,'요나단이 이르되 내 아버지께서 이 땅을 곤란하게 하셨도다 보라 내가 이 꿀 조금을 맛보고도 내 눈이 이렇게 밝아졌거든',7538),
('1sa-14-30','1sa','사무엘상',14,30,'하물며 백성이 오늘 그 대적에게서 탈취하여 얻은 것을 임의로 먹었더라면 블레셋 사람을 살륙함이 더욱 많지 아니하였겠느냐',7539),
('1sa-14-31','1sa','사무엘상',14,31,'그 날에 백성이 믹마스에서부터 아얄론에 이르기까지 블레셋 사람들을 쳤으므로 그들이 심히 피곤한지라',7540),
('1sa-14-32','1sa','사무엘상',14,32,'백성이 이에 탈취한 물건에 달려가서 양과 소와 송아지들을 끌어다가 그것을 땅에서 잡아 피째 먹었더니',7541),
('1sa-14-33','1sa','사무엘상',14,33,'무리가 사울에게 전하여 이르되 보소서 백성이 고기를 피째 먹어 여호와께 범죄하였나이다 사울이 이르되 너희가 믿음 없이 행하였도다 이제 큰 돌을 내게로 굴려 오라 하고',7542),
('1sa-14-34','1sa','사무엘상',14,34,'또 사울이 이르되 너희는 백성 중에 흩어져 다니며 그들에게 이르기를 사람은 각기 소와 양을 이리로 끌어다가 여기서 잡아 먹되 피째로 먹어 여호와께 범죄하지 말라 하라 하매 그 밤에 모든 백성이 각각 자기의 소를 끌어다가 거기서 잡으니라',7543),
('1sa-14-35','1sa','사무엘상',14,35,'사울이 여호와를 위하여 제단을 쌓았으니 이는 그가 여호와를 위하여 처음 쌓은 제단이었더라',7544),
('1sa-14-36','1sa','사무엘상',14,36,'사울이 이르되 우리가 밤에 블레셋 사람들을 추격하여 동틀 때까지 그들 중에서 탈취하고 한 사람도 남기지 말자 무리가 이르되 왕의 생각에 좋은 대로 하소서 할 때에 제사장이 이르되 이리로 와서 하나님께로 나아가사이다 하매',7545),
('1sa-14-37','1sa','사무엘상',14,37,'사울이 하나님께 묻자오되 내가 블레셋 사람들을 추격하리이까 주께서 그들을 이스라엘의 손에 넘기시겠나이까 하되 그 날에 대답하지 아니하시는지라',7546),
('1sa-14-38','1sa','사무엘상',14,38,'사울이 이르되 너희 군대의 지휘관들아 다 이리로 오라 오늘 이 죄가 누구에게 있나 알아보자',7547),
('1sa-14-39','1sa','사무엘상',14,39,'이스라엘을 구원하신 여호와께서 살아 계심을 두고 맹세하노니 내 아들 요나단에게 있다 할지라도 반드시 죽으리라 하되 모든 백성 중 한 사람도 대답하지 아니하매',7548),
('1sa-14-40','1sa','사무엘상',14,40,'이에 그가 온 이스라엘에게 이르되 너희는 저쪽에 있으라 나와 내 아들 요나단은 이쪽에 있으리라 백성이 사울에게 말하되 왕의 생각에 좋은 대로 하소서 하니라',7549),
('1sa-14-41','1sa','사무엘상',14,41,'이에 사울이 이스라엘의 하나님 여호와께 아뢰되 원하건대 실상을 보이소서 하였더니 요나단과 사울이 뽑히고 백성은 면한지라',7550),
('1sa-14-42','1sa','사무엘상',14,42,'사울이 이르되 나와 내 아들 요나단 사이에 뽑으라 하였더니 요나단이 뽑히니라',7551),
('1sa-14-43','1sa','사무엘상',14,43,'사울이 요나단에게 이르되 네가 행한 것을 내게 말하라 요나단이 말하여 이르되 내가 다만 내 손에 가진 지팡이 끝으로 꿀을 조금 맛보았을 뿐이오나 내가 죽을 수밖에 없나이다',7552),
('1sa-14-44','1sa','사무엘상',14,44,'사울이 이르되 요나단아 네가 반드시 죽으리라 그렇지 않으면 하나님이 내게 벌을 내리시고 또 내리시기를 원하노라 하니',7553),
('1sa-14-45','1sa','사무엘상',14,45,'백성이 사울에게 말하되 이스라엘에 이 큰 구원을 이룬 요나단이 죽겠나이까 결단코 그렇지 아니하니이다 여호와의 살아 계심을 두고 맹세하옵나니 그의 머리털 하나도 땅에 떨어지지 아니할 것은 그가 오늘 하나님과 동역하였음이니이다 하여 백성이 요나단을 구원하여 죽지 않게 하니라',7554),
('1sa-14-46','1sa','사무엘상',14,46,'사울이 블레셋 사람들 추격하기를 그치고 올라가매 블레셋 사람들이 자기 곳으로 돌아가니라',7555),
('1sa-14-47','1sa','사무엘상',14,47,'사울이 이스라엘 왕위에 오른 후에 사방에 있는 모든 대적 곧 모압과 암몬 자손과 에돔과 소바의 왕들과 블레셋 사람들을 쳤는데 향하는 곳마다 이겼고',7556),
('1sa-14-48','1sa','사무엘상',14,48,'용감하게 아말렉 사람들을 치고 이스라엘을 그 약탈하는 자들의 손에서 건졌더라',7557),
('1sa-14-49','1sa','사무엘상',14,49,'사울의 아들은 요나단과 이스위와 말기수아요 그의 두 딸의 이름은 이러하니 맏딸의 이름은 메랍이요 작은 딸의 이름은 미갈이며',7558),
('1sa-14-50','1sa','사무엘상',14,50,'사울의 아내의 이름은 아히노암이니 아히마아스의 딸이요 그의 군사령관의 이름은 아브넬이니 사울의 숙부 넬의 아들이며',7559),
('1sa-14-51','1sa','사무엘상',14,51,'사울의 아버지는 기스요 아브넬의 아버지는 넬이니 아비엘의 아들이었더라',7560),
('1sa-14-52','1sa','사무엘상',14,52,'사울이 사는 날 동안에 블레셋 사람과 큰 싸움이 있었으므로 사울이 힘 센 사람이나 용감한 사람을 보면 그들을 불러모았더라',7561),
('1sa-15-1','1sa','사무엘상',15,1,'사무엘이 사울에게 이르되 여호와께서 나를 보내어 왕에게 기름을 부어 그의 백성 이스라엘 위에 왕으로 삼으셨은즉 이제 왕은 여호와의 말씀을 들으소서',7562),
('1sa-15-2','1sa','사무엘상',15,2,'만군의 여호와께서 이같이 말씀하시기를 아말렉이 이스라엘에게 행한 일 곧 애굽에서 나올 때에 길에서 대적한 일로 내가 그들을 벌하노니',7563),
('1sa-15-3','1sa','사무엘상',15,3,'지금 가서 아말렉을 쳐서 그들의 모든 소유를 남기지 말고 진멸하되 남녀와 소아와 젖 먹는 아이와 우양과 낙타와 나귀를 죽이라 하셨나이다 하니',7564),
('1sa-15-4','1sa','사무엘상',15,4,'사울이 백성을 소집하고 그들을 들라임에서 세어 보니 보병이 이십만 명이요 유다 사람이 만 명이라',7565),
('1sa-15-5','1sa','사무엘상',15,5,'사울이 아말렉 성에 이르러 골짜기에 복병시키니라',7566),
('1sa-15-6','1sa','사무엘상',15,6,'사울이 겐 사람에게 이르되 아말렉 사람 중에서 떠나 가라 그들과 함께 너희를 멸하게 될까 하노라 이스라엘 모든 자손이 애굽에서 올라올 때에 너희가 그들을 선대하였느니라 이에 겐 사람이 아말렉 사람 중에서 떠나니라',7567),
('1sa-15-7','1sa','사무엘상',15,7,'사울이 하윌라에서부터 애굽 앞 술에 이르기까지 아말렉 사람을 치고',7568),
('1sa-15-8','1sa','사무엘상',15,8,'아말렉 사람의 왕 아각을 사로잡고 칼날로 그의 모든 백성을 진멸하였으되',7569),
('1sa-15-9','1sa','사무엘상',15,9,'사울과 백성이 아각과 그의 양과 소의 가장 좋은 것 또는 기름진 것과 어린 양과 모든 좋은 것을 남기고 진멸하기를 즐겨 아니하고 가치 없고 하찮은 것은 진멸하니라',7570),
('1sa-15-10','1sa','사무엘상',15,10,'여호와의 말씀이 사무엘에게 임하니라 이르시되',7571),
('1sa-15-11','1sa','사무엘상',15,11,'내가 사울을 왕으로 세운 것을 후회하노니 그가 돌이켜서 나를 따르지 아니하며 내 명령을 행하지 아니하였음이니라 하신지라 사무엘이 근심하여 온 밤을 여호와께 부르짖으니라',7572),
('1sa-15-12','1sa','사무엘상',15,12,'사무엘이 사울을 만나려고 아침에 일찍이 일어났더니 어떤 사람이 사무엘에게 말하여 이르되 사울이 갈멜에 이르러 자기를 위하여 기념비를 세우고 발길을 돌려 길갈로 내려갔다 하는지라',7573),
('1sa-15-13','1sa','사무엘상',15,13,'사무엘이 사울에게 이른즉 사울이 그에게 이르되 원하건대 당신은 여호와께 복을 받으소서 내가 여호와의 명령을 행하였나이다 하니',7574),
('1sa-15-14','1sa','사무엘상',15,14,'사무엘이 이르되 그러면 내 귀에 들려오는 이 양의 소리와 내게 들리는 소의 소리는 어찌 됨이니이까 하니라',7575),
('1sa-15-15','1sa','사무엘상',15,15,'사울이 이르되 그것은 무리가 아말렉 사람에게서 끌어 온 것인데 백성이 당신의 하나님 여호와께 제사하려 하여 양들과 소들 중에서 가장 좋은 것을 남김이요 그 외의 것은 우리가 진멸하였나이다 하는지라',7576),
('1sa-15-16','1sa','사무엘상',15,16,'사무엘이 사울에게 이르되 가만히 계시옵소서 간 밤에 여호와께서 내게 이르신 것을 왕에게 말하리이다 하니 그가 이르되 말씀하소서',7577),
('1sa-15-17','1sa','사무엘상',15,17,'사무엘이 이르되 왕이 스스로 작게 여길 그 때에 이스라엘 지파의 머리가 되지 아니하셨나이까 여호와께서 왕에게 기름을 부어 이스라엘 왕을 삼으시고',7578),
('1sa-15-18','1sa','사무엘상',15,18,'또 여호와께서 왕을 길로 보내시며 이르시기를 가서 죄인 아말렉 사람을 진멸하되 다 없어지기까지 치라 하셨거늘',7579),
('1sa-15-19','1sa','사무엘상',15,19,'어찌하여 왕이 여호와의 목소리를 청종하지 아니하고 탈취하기에만 급하여 여호와께서 악하게 여기시는 일을 행하였나이까',7580),
('1sa-15-20','1sa','사무엘상',15,20,'사울이 사무엘에게 이르되 나는 실로 여호와의 목소리를 청종하여 여호와께서 보내신 길로 가서 아말렉 왕 아각을 끌어 왔고 아말렉 사람들을 진멸하였으나',7581),
('1sa-15-21','1sa','사무엘상',15,21,'다만 백성이 그 마땅히 멸할 것 중에서 가장 좋은 것으로 길갈에서 당신의 하나님 여호와께 제사하려고 양과 소를 끌어 왔나이다 하는지라',7582),
('1sa-15-22','1sa','사무엘상',15,22,'사무엘이 이르되 여호와께서 번제와 다른 제사를 그의 목소리를 청종하는 것을 좋아하심 같이 좋아하시겠나이까 순종이 제사보다 낫고 듣는 것이 숫양의 기름보다 나으니',7583),
('1sa-15-23','1sa','사무엘상',15,23,'이는 거역하는 것은 점치는 죄와 같고 완고한 것은 사신 우상에게 절하는 죄와 같음이라 왕이 여호와의 말씀을 버렸으므로 여호와께서도 왕을 버려 왕이 되지 못하게 하셨나이다 하니',7584),
('1sa-15-24','1sa','사무엘상',15,24,'사울이 사무엘에게 이르되 내가 범죄하였나이다 내가 여호와의 명령과 당신의 말씀을 어긴 것은 내가 백성을 두려워하여 그들의 말을 청종하였음이니이다',7585),
('1sa-15-25','1sa','사무엘상',15,25,'청하오니 지금 내 죄를 사하고 나와 함께 돌아가서 나로 하여금 여호와께 경배하게 하소서 하니',7586),
('1sa-15-26','1sa','사무엘상',15,26,'사무엘이 사울에게 이르되 나는 왕과 함께 돌아가지 아니하리니 이는 왕이 여호와의 말씀을 버렸으므로 여호와께서 왕을 버려 이스라엘 왕이 되지 못하게 하셨음이니이다 하고',7587),
('1sa-15-27','1sa','사무엘상',15,27,'사무엘이 가려고 돌아설 때에 사울이 그의 겉옷자락을 붙잡으매 찢어진지라',7588),
('1sa-15-28','1sa','사무엘상',15,28,'사무엘이 그에게 이르되 여호와께서 오늘 이스라엘 나라를 왕에게서 떼어 왕보다 나은 왕의 이웃에게 주셨나이다',7589),
('1sa-15-29','1sa','사무엘상',15,29,'이스라엘의 지존자는 거짓이나 변개함이 없으시니 그는 사람이 아니시므로 결코 변개하지 않으심이니이다 하니',7590),
('1sa-15-30','1sa','사무엘상',15,30,'사울이 이르되 내가 범죄하였을지라도 이제 청하옵나니 내 백성의 장로들 앞과 이스라엘 앞에서 나를 높이사 나와 함께 돌아가서 내가 당신의 하나님 여호와께 경배하게 하소서 하더라',7591),
('1sa-15-31','1sa','사무엘상',15,31,'이에 사무엘이 돌이켜 사울을 따라가매 사울이 여호와께 경배하니라',7592),
('1sa-15-32','1sa','사무엘상',15,32,'사무엘이 이르되 너희는 아말렉 사람의 왕 아각을 내게로 끌어 오라 하였더니 아각이 즐거이 오며 이르되 진실로 사망의 괴로움이 지났도다 하니라',7593),
('1sa-15-33','1sa','사무엘상',15,33,'사무엘이 이르되 네 칼이 여인들에게 자식이 없게 한 것 같이 여인 중 네 어미에게 자식이 없으리라 하고 그가 길갈에서 여호와 앞에서 아각을 찍어 쪼개니라',7594),
('1sa-15-34','1sa','사무엘상',15,34,'이에 사무엘은 라마로 가고 사울은 사울 기브아 자기의 집으로 올라가니라',7595),
('1sa-15-35','1sa','사무엘상',15,35,'사무엘이 죽는 날까지 사울을 다시 가서 보지 아니하였으니 이는 그가 사울을 위하여 슬퍼함이었고 여호와께서는 사울을 이스라엘 왕으로 삼으신 것을 후회하셨더라',7596),
('1sa-16-1','1sa','사무엘상',16,1,'여호와께서 사무엘에게 이르시되 내가 이미 사울을 버려 이스라엘 왕이 되지 못하게 하였거늘 네가 그를 위하여 언제까지 슬퍼하겠느냐 너는 뿔에 기름을 채워 가지고 가라 내가 너를 베들레헴 사람 이새에게로 보내리니 이는 내가 그의 아들 중에서 한 왕을 보았느니라 하시는지라',7597),
('1sa-16-2','1sa','사무엘상',16,2,'사무엘이 이르되 내가 어찌 갈 수 있으리이까 사울이 들으면 나를 죽이리이다 하니 여호와께서 이르시되 너는 암송아지를 끌고 가서 말하기를 내가 여호와께 제사를 드리러 왔다 하고',7598),
('1sa-16-3','1sa','사무엘상',16,3,'이새를 제사에 청하라 내가 네게 행할 일을 가르치리니 내가 네게 알게 하는 자에게 나를 위하여 기름을 부을지니라',7599),
('1sa-16-4','1sa','사무엘상',16,4,'사무엘이 여호와의 말씀대로 행하여 베들레헴에 이르매 성읍 장로들이 떨며 그를 영접하여 이르되 평강을 위하여 오시나이까',7600),
('1sa-16-5','1sa','사무엘상',16,5,'이르되 평강을 위함이니라 내가 여호와께 제사하러 왔으니 스스로 성결하게 하고 와서 나와 함께 제사하자 하고 이새와 그의 아들들을 성결하게 하고 제사에 청하니라',7601),
('1sa-16-6','1sa','사무엘상',16,6,'그들이 오매 사무엘이 엘리압을 보고 마음에 이르기를 여호와의 기름 부으실 자가 과연 주님 앞에 있도다 하였더니',7602),
('1sa-16-7','1sa','사무엘상',16,7,'여호와께서 사무엘에게 이르시되 그의 용모와 키를 보지 말라 내가 이미 그를 버렸노라 내가 보는 것은 사람과 같지 아니하니 사람은 외모를 보거니와 나 여호와는 중심을 보느니라 하시더라',7603),
('1sa-16-8','1sa','사무엘상',16,8,'이새가 아비나답을 불러 사무엘 앞을 지나가게 하매 사무엘이 이르되 이도 여호와께서 택하지 아니하셨느니라 하니',7604),
('1sa-16-9','1sa','사무엘상',16,9,'이새가 삼마로 지나게 하매 사무엘이 이르되 이도 여호와께서 택하지 아니하셨느니라 하니라',7605),
('1sa-16-10','1sa','사무엘상',16,10,'이새가 그의 아들 일곱을 다 사무엘 앞으로 지나가게 하나 사무엘이 이새에게 이르되 여호와께서 이들을 택하지 아니하셨느니라 하고',7606),
('1sa-16-11','1sa','사무엘상',16,11,'또 사무엘이 이새에게 이르되 네 아들들이 다 여기 있느냐 이새가 이르되 아직 막내가 남았는데 그는 양을 지키나이다 사무엘이 이새에게 이르되 사람을 보내어 그를 데려오라 그가 여기 오기까지는 우리가 식사 자리에 앉지 아니하겠노라',7607),
('1sa-16-12','1sa','사무엘상',16,12,'이에 사람을 보내어 그를 데려오매 그의 빛이 붉고 눈이 빼어나고 얼굴이 아름답더라 여호와께서 이르시되 이가 그니 일어나 기름을 부으라 하시는지라',7608),
('1sa-16-13','1sa','사무엘상',16,13,'사무엘이 기름 뿔병을 가져다가 그의 형제 중에서 그에게 부었더니 이 날 이후로 다윗이 여호와의 영에게 크게 감동되니라 사무엘이 떠나서 라마로 가니라',7609),
('1sa-16-14','1sa','사무엘상',16,14,'여호와의 영이 사울에게서 떠나고 여호와께서 부리시는 악령이 그를 번뇌하게 한지라',7610),
('1sa-16-15','1sa','사무엘상',16,15,'사울의 신하들이 그에게 이르되 보소서 하나님께서 부리시는 악령이 왕을 번뇌하게 하온즉',7611),
('1sa-16-16','1sa','사무엘상',16,16,'원하건대 우리 주께서는 당신 앞에서 모시는 신하들에게 명령하여 수금을 잘 타는 사람을 구하게 하소서 하나님께서 부리시는 악령이 왕에게 이를 때에 그가 손으로 타면 왕이 나으시리이다 하는지라',7612),
('1sa-16-17','1sa','사무엘상',16,17,'사울이 신하에게 이르되 나를 위하여 잘 타는 사람을 구하여 내게로 데려오라 하니',7613),
('1sa-16-18','1sa','사무엘상',16,18,'소년 중 한 사람이 대답하여 이르되 내가 베들레헴 사람 이새의 아들을 본즉 수금을 탈 줄 알고 용기와 무용과 구변이 있는 준수한 자라 여호와께서 그와 함께 계시더이다 하더라',7614),
('1sa-16-19','1sa','사무엘상',16,19,'사울이 이에 전령들을 이새에게 보내어 이르되 양 치는 네 아들 다윗을 내게로 보내라 하매',7615),
('1sa-16-20','1sa','사무엘상',16,20,'이새가 떡과 한 가죽부대의 포도주와 염소 새끼를 나귀에 실리고 그의 아들 다윗을 시켜 사울에게 보내니',7616),
('1sa-16-21','1sa','사무엘상',16,21,'다윗이 사울에게 이르러 그 앞에 모셔 서매 사울이 그를 크게 사랑하여 자기의 무기를 드는 자로 삼고',7617),
